slide_1: {'title': 'The Hidden Cost of Your Fragmented Creator Tool Stack', 'body': 'Are you paying more than just money for your content tools? Discover the true price of fragmentation and how to unify your CreatorOps.', 'visual_cue': 'Bold title, IncuBrix logo, graphic showing multiple disconnected app icons.'}
slide_2: {'title': 'The Problem: Cognitive Friction & High Costs', 'body': "Solo creators and small teams juggle 4-6 platforms, using 4+ separate tools. This isn't just $97+/month; it's 14.5 hours of production for every 1 hour of recording.", 'visual_cue': "Infographic showing a person's head with gears, dollar signs, and a clock icon. List of common tools (Descript, Opus Clip, Buffer, Jasper)."}
slide_3: {'title': 'Meet the Fragmented Creator Tool Stack:', 'body': '1. Video Editing: Descript/Premiere Pro ($24/mo)\n2. Vertical Clipping: Opus Clip/Klap ($19/mo)\n3. Scheduling: Buffer/Hootsuite ($15/mo)\n4. AI Writing: Jasper/ChatGPT ($39/mo)\nTotal: $97+/month + endless context switching.', 'visual_cue': 'Grid of app logos with their respective monthly costs. Highlight the total cost.'}
slide_4: {'title': 'The IncuBrix Solution: Unified CreatorOps', 'body': 'We engineered IncuBrix to collapse the entire content lifecycle into a single hub. Ideation, editing, voice cloning, and publishing – all in one place.', 'visual_cue': 'Clean IncuBrix UI screenshot, showing different modules (Thought Inbox, Editor, Voice Hub, Publishing) seamlessly integrated.'}
slide_5: {'title': 'Real Results: Time & Cost Savings', 'body': '✅ 85% reduction in weekly production time (14.2 hrs to 2.1 hrs)\n✅ Publishing frequency up 300% (2.4 to 9.8 posts/week)\n✅ Software spend consolidated from $97/month to $29/month.', 'visual_cue': 'Before/After graphic with time and money saved. Green checkmarks for each achievement.'}
